PNG','pdf-merger.php'=>'📑 PDF Merger','pdf-splitter.php'=>'📄 PDF Splitter','pdf-compressor.php'=>'📦 PDF Compressor','png-to-pdf.php'=>'📄 PNG to PDF','text-to-pdf.php'=>'📝 Text to PDF','qr-generator.php'=>'🔐 QR Code Generator','qr-reader.php'=>'📷 QR Code Reader','age-calculator.php'=>'🎂 Age Calculator','percentage-calculator.php'=>'% Percentage Calculator','bmi-calculator.php'=>'⚖️ BMI Calculator','unit-converter.php'=>'📏 Unit Converter','stopwatch-timer.php'=>'⏱️ Stopwatch Timer','lorem-ipsum-generator.php'=>'📄 Lorem Ipsum','unix-timestamp.php'=>'🕐 Unix Timestamp','timestamp-converter.php'=>'🕐 Timestamp Converter','uuid-generator.php'=>'🆔 UUID Generator','random-number-generator.php'=>'🎲 Random Number Generator','json-formatter.php'=>'{} JSON Formatter','word-counter.php'=>'📝 Word Counter','case-converter.php'=>'🔤 Case Converter','url-encoder.php'=>'🔗 URL Encoder'];foreach($items as $f=>$n):?><a class="<?=basename($_SERVER['SCRIPT_NAME'])===$f?'active':''?>" href="/tools/<?=htmlspecialchars($f,ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars($n)?></a><?php endforeach;?><a href="/tool.php">View All Tools →</a></aside></div></main><script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script><script>const file=document.getElementById('file'),upload=document.getElementById('upload'),result=document.getElementById('result'),video=document.getElementById('video'),cameraBtn=document.getElementById('cameraBtn');upload.onclick=()=>file.click();file.onchange=()=>{const f=file.files[0];if(!f)return;const r=new FileReader();r.onload=()=>decodeImage(r.result);r.readAsDataURL(f)};function decodeImage(src){const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),x=c.getContext('2d');c.width=img.naturalWidth;c.height=img.naturalHeight;x.drawImage(img,0,0);const q=jsQR(x.getImageData(0,0,c.width,c.height).data,c.width,c.height);result.textContent=q?'QR Content: '+q.data:'No QR code found in this image.'};img.src=src}let stream;cameraBtn.onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=stream;video.style.display='block';scan()}catch(e){result.textContent='Camera access was not allowed or is unavailable.'}};function scan(){if(video.readyState<2){requestAnimationFrame(scan);return}const c=document.createElement('canvas'),x=c.getContext('2d');c.width=video.videoWidth;c.height=video.videoHeight;x.drawImage(video,0,0,c.width,c.height);const q=jsQR(x.getImageData(0,0,c.width,c.height).data,c.width,c.height);if(q){result.textContent='QR Content: '+q.data;if(stream)stream.getTracks().forEach(t=>t.stop());return}requestAnimationFrame(scan)}</script>
